        ... on ItineraryProduct {
          productInfo {
            ...ProductInfo
          }
        }
        ... on AncillariesProduct {
          __typename
          id {
            id
            type
          }
          productInfo {
            cabinBagsSelections {
              segment
              section
              type

              priceBreakdown {
                primeFee {
                  amount
                  currency
                }
                fee {
                  amount
                  currency
                }
              }
            }
          }
        }
      }
      travellers {
        numPassenger
        personalInfo {
          ageType
        }
      }
    }
  }
","variables":{"request":{"shoppingInfo":{"shoppingId":"19340799586","shoppingType":"CART"}}},"operationName":"GetShoppingBundleCabinBags"}

