{"query":"
  query itinerarySearch($searchRequest: SearchRequest!) {
    itinerarySearch(searchRequest: $searchRequest) {
      searchId
      searchCode {
        code
        message
      }
      priceTypeDisplayed
      itineraries {
        ...ItinerarySearchItineraryFragment
      }
      externalSelection {
        id
        segmentKeys
      }
      campaignsItineraryLists {
        campaignItineraryIds
        campaignKey
      }
      itineraryAlternativesList {
        itineraryId
        alternativeItineraries {
          id
          cashback {
            amount
            currency
          }
        }
      }
      freeCancellationItineraryIds
      fees {
        id
        type {
          id
          name
          paymentMethod
        }
      }
      locations {
        id
        location {
          id
          iata
          cityIata
          cityName
          name
          countryName
          locationType
        }
      }
      carriers {
        id
        carrier {
          id
          name
          supportUrl
        }
      }
      insuranceOffers {
        id
        insuranceOffer {
          id
          url
          policy
        }
      }
      carbonFootprints {
        id
        carbonFootprint {
          isEco
          ecoPercentageThanAverage
          totalCo2Kilos
          totalCo2eKilos
        }
      }
      campaignConfigs {
        id
        campaignConfig {
          primeDayConfig {
            isPrimeDayFare
            primeDayFareType
          }
        }
      }
      trackingInfo {
        returningUserDeviceId
        airlinePositionTracking {
          ...AirlineTrackingInfo
        }
        airlineSteeringTracking {
          ...AirlineTrackingInfo
        }
      }
    }
  }

  fragment AirlineTrackingInfo on AirlineTracking {
    carrier
    sortingPosition {
      ...AirlineTrackingPositionInfo
    }
    preBoostingPosition {
      ...AirlineTrackingPositionInfo
    }
  }

  fragment AirlineTrackingPositionInfo on TrackingPosition {
    crossFaring
    position
    itineraryId
  }



  fragment ItinerarySearchItineraryFragment on ItinerarySearchResult {
    id
    isFareUpgradeAvailable
    key
    hotelXSellingEnabled
    meRating
    fees {
      price {
        amount
        currency
      }
      type
    }
    ticketsLeft
    legs {
      segmentKeys
      segments {
        ...SegmentInfo
      }
    }
    transportTypes
    carbonFootprintId
    campaignConfigId
    perks {
      primeDiscount {
        amount
        currency
      }
      extraPrimeCoupon {
        amount
        currency
      }
      primeDiscountPerPassenger {
        amount
        currency
      }
      extraPrimeCouponPerPassenger {
        amount
        currency
      }
    }
  }


  fragment SegmentInfo on ItinerarySearchResultSegment {
    id
    duration
    carrierId
    sections {
      ...SectionInfo
    }
    baggageCondition
    transportTypes
  }


  fragment SectionInfo on ItinerarySearchResultSection {
    id
    departureDate
    arrivalDate
    duration
    departureId
    destinationId
    carrierId
    operatingCarrierId
    technicalStops {
      ...TechnicalStop
    }
    cabinClass
    flightCode
    departureTerminal
    arrivalTerminal
    vehicleModel
    transportType
    insuranceOfferId
  }


  fragment TechnicalStop on TechnicalStop {
    location {
      id
      iata
      cityIata
      cityName
      name
      countryName
      locationType
    }
    arrivalDate
    departureDate
  }




