                primeFee {
                  amount
                  currency
                }
                fee {
                  amount
                  currency
                }
              }
            }
          }
        }
      }
      travellers {
        numPassenger
        personalInfo {
          ageType
        }
      }
    }
  }
","variables":{"request":{"shoppingInfo":{"shoppingId":"19340866722","shoppingType":"CART"}}},"operationName":"GetShoppingBundleCabinBags"}

