{"query":"


  fragment SubscriptionOffer on SubscriptionResponse {
    price {
      amount
      currency
    }
    offerId
    renewalPrice {
      amount
      currency
    }
    duration {
      amount
      timeUnit
    }
    renewalDuration {
      amount
      timeUnit
    }
    subscriptionPeriod
    type
  }

  fragment MembershipSubscriptionResponse on MembershipSubscriptionResponse {
    offerAdded {
      ...SubscriptionOffer
    }
    primeMember {
      name
      lastNames
    }
  }

  query MembershipProduct(
    $membershipProductRequest: GetMembershipProductRequest
  ) {
    membershipProduct(membershipProductRequest: $membershipProductRequest) {
      ...MembershipSubscriptionResponse
    }
  }
","variables":{"membershipProductRequest":{"shoppingInfo":{"shoppingId":"19340866722","shoppingType":"CART"}}},"operationName":"MembershipProduct"}

{"query":"
  query GetShoppingBundle(
    $request: ShoppingBundleRequest!
    $withBuyer: Boolean!
    $withTravellers: Boolean!
    $withProductList: Boolean!
  ) {
    getShoppingBundle(request: $request) {
      membershipPerks {
        perks {
          discount {
            currency
            amount
          }
          isApplied
          perkType
        }
      }
      buyer @include(if: $withBuyer) {
        mail
        name
        lastNames
        userRegistered
      }
      travellers @include(if: $withTravellers) {
        numPassenger
        personalInfo {
          name
          firstLastName
          secondLastName
        }
      }
      products @include(if: $withProductList) {
        id {
          type
        }
        price {
          amount
          currency
        }
      }
    }
  }
","variables":{"request":{"shoppingInfo":{"shoppingId":"19340866722","shoppingType":"CART"}},"withBuyer":false,"withTravellers":false,"withProductList":false},"operationName":"GetShoppingBundle"}

{"query":"
  query GetPriceBreakdownPriceSummary($request: PriceBreakDownRequest!) {
    getCartPriceBreakDown(request: $request) {
      items {
        type
        ... on AccommodationPriceBreakDownItem {
          selectedCustomerPriceType
        }
      }
    }
  }
","variables":{"request":{"shoppingInfo":{"shoppingId":"19340866722","shoppingType":"CART"}}},"operationName":"GetPriceBreakdownPriceSummary"}

