  query GetShoppingBundleCabinBags($request: ShoppingBundleRequest) {
    getShoppingBundle(request: $request) {
      products {
        __typename
        id {
          id
          type
        }
        ... on ItineraryProduct {
          productInfo {
            ...ProductInfo
          }
        }
        ... on AncillariesProduct {
          __typename
          id {
            id
            type
          }
          productInfo {
            cabinBagsSelections {
              segment
              section
              type

              priceBreakdown {
                primeFee {
                  amount
                  currency
                }
                fee {
                  amount
                  currency
                }
              }
            }
          }
        }
      }
      travellers {
        numPassenger
        personalInfo {
          ageType
        }
      }
    }
  }
","variables":{"request":{"shoppingInfo":{"shoppingId":"19340908011","shoppingType":"CART"}}},"operationName":"GetShoppingBundleCabinBags"}

